function alternarHoy(id) {
  const h = habitos.find(x => x.id === id);
  const dia = hoy();
  if (h.hechos.includes(dia)) {
    h.hechos = h.hechos.filter(d => d !== dia);
  } else {
    h.hechos.push(dia);
  }
  pintar();
}

const CLAVE = 'mis-habitos';
let habitos = cargar();

function cargar() {
  try {
    return JSON.parse(localStorage.getItem(CLAVE)) || [];
  } catch (e) {
    return [];
  }
}

function guardar() {
  localStorage.setItem(CLAVE, JSON.stringify(habitos));
}
